import { AnimatedIconFrame, type AnimatedIconProps } from "../icon-frame";
import "./heart.css";

const heartPath =
  "M19.463 3.994c-2.682-1.645-5.023-.982-6.429.074c-.576.433-.864.65-1.034.65s-.458-.217-1.034-.65C9.56 3.012 7.219 2.349 4.537 3.994C1.018 6.153.222 13.274 8.34 19.284C9.886 20.427 10.659 21 12 21s2.114-.572 3.66-1.717c8.118-6.008 7.322-13.13 3.803-15.289";

type Props = AnimatedIconProps & {
  filled?: boolean;
};

export function AnimatedHeartIcon({ filled = false, ...props }: Props) {
  return (
    <AnimatedIconFrame name="heart" data-filled={filled ? "" : undefined} {...props}>
      <g data-part="heart">
        <path data-part="fill" d={heartPath} />
        <path d={heartPath} />
      </g>
    </AnimatedIconFrame>
  );
}

.animated-icon[data-icon="heart"] [data-part="fill"] {
  fill: currentColor;
  stroke: none;
  opacity: 0;
  transform: scale(0);
  transition:
    transform 180ms var(--ease-icon),
    opacity 120ms linear;
}

.animated-icon[data-icon="heart"][data-filled] [data-part="fill"] {
  opacity: 1;
  transform: none;
  transition:
    transform 420ms cubic-bezier(0.34, 1.56, 0.64, 1),
    opacity 120ms linear;
}

.animated-icon[data-icon="heart"] :is([data-part="heart"], [data-part="fill"]) {
  transform-origin: 12px 13px;
}

:is([data-icon-hover] .animated-icon, .animated-icon[data-icon-hover], .animated-icon[data-play]) {
  &[data-icon="heart"] [data-part="heart"] {
    animation-name: icon-heart-beat;
    animation-duration: var(--icon-duration-long);
  }
}

@keyframes icon-heart-beat {
  18% {
    transform: rotate(-8deg) scale(0.9);
  }
  46% {
    transform: rotate(6deg) scale(1.16);
  }
  72% {
    transform: rotate(-2deg) scale(0.98);
  }
}
